ded, never replaced.","The hook files are still written and the result notes that hooksPath was not set.","A fresh yes repo has enforcement from the first commit."],"teardown_steps":[],"required_permissions":[],"safety_constraints":[],"verification_policy_snapshot":{"mode":"requirements","verifiers":{"script":{"kind":"script","evidence_kind":"test_result","command":["pnpm","-s","vitest","run","packages/core/test/init/scaffold-git-hooks.test.ts"],"inputs":["packages/core/test/init/scaffold-git-hooks.test.ts","packages/core/src/init/scaffold.ts"]}},"requirements":[{"evidence_kind":"test_result","required_verifiers":["script"],"minimum_count":1}]},"approval_policy_snapshot":{"mode":"none"},"approval_resolution_required_at_run_start":false,"required_evidence":[{"evidence_kind":"test_result","required_verifiers":["script"],"minimum_count":1,"status":"missing"}],"evidence_summary":{"readiness":"missing","active_evidence_ids":[],"basis":"no_active_evidence"},"freshness_summary":{"state":"unknown","basis":"missing_evidence"},"known_gaps":[{"code":"evidence_missing","message":"Required evidence is missing; live performance is still required.","severity":"warning"}],"selection_reasons":["Core value use case.","Golden journey coverage.","Occasional usage frequency."],"selection_reason_codes":["value_core","journey_golden","frequency_occasional"],"score_components":{"changed":0,"value":300,"journey":50,"frequency":20}},{"plan_item_id":"item.plugin.install.codex_from_github","presentation_format":"reviewing","delivery_kind":"evidence_review","scenario_scope":"explicit","use_case_id":"plugin.install.codex_from_github","use_case_title":"Codex installs the plugin from its marketplace","scenario_ids":["plugin.install.codex_from_github.golden_codex_manifest","plugin.install.codex_from_github.bad_root_mcp_json_would_break_copilot","plugin.install.codex_from_github.edge_live_skills","plugin.install.codex_from_github.edge_live_mcp_not_yet_observed"],"use_case_content_hash":"sha256:ca84a